-- Dashing — remote schema baseline
--
-- Reconstructed on 2026-10-15 from the live project (ozeixaolbickpauayjcu)
-- catalog. It reproduces the database exactly as it stood after the six
-- original migrations (now in supabase/migrations_archive/), INCLUDING the
-- defects fixed by the next migration, so that a fresh `supabase db reset`
-- yields the same schema as production.
--
-- Do not edit this file to change behaviour. Add a new migration instead.

-- ---------------------------------------------------------------------------
-- Schemas and types
-- ---------------------------------------------------------------------------

create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated, service_role;

create type public.post_status as enum ('draft', 'published', 'hidden', 'removed');
create type public.report_reason as enum (
  'underage', 'nudity_or_sexual_content', 'harassment', 'spam', 'copyright', 'other'
);

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table public.profiles (
  id uuid not null,
  username text not null,
  display_name text,
  avatar_url text,
  bio text,
  date_of_birth date not null,
  is_moderator boolean default false not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  country text,
  city text,
  default_max_viewer_age smallint
);
alter table public.profiles add constraint profiles_pkey primary key (id);
alter table public.profiles add constraint profiles_id_fkey foreign key (id) references auth.users(id) on delete cascade;
alter table public.profiles add constraint profiles_username_format check (username ~ '^[a-z0-9_]+$'::text);
alter table public.profiles add constraint profiles_username_length check (char_length(username) >= 3 and char_length(username) <= 32);
alter table public.profiles add constraint profiles_country_format check (country is null or (country = btrim(country) and char_length(country) >= 2 and char_length(country) <= 100));
alter table public.profiles add constraint profiles_city_format check (city is null or (city = btrim(city) and char_length(city) >= 1 and char_length(city) <= 100));
alter table public.profiles add constraint profiles_default_max_viewer_age_bounds check (default_max_viewer_age is null or (default_max_viewer_age >= 18 and default_max_viewer_age <= 100));
create unique index profiles_username_lower_key on public.profiles using btree (lower(username));
comment on column public.profiles.default_max_viewer_age is 'Preferred viewer age ceiling for new posts. NULL = no restriction.';

create table public.posts (
  id uuid default gen_random_uuid() not null,
  author_id uuid not null,
  caption text,
  media_urls text[] not null,
  status public.post_status default 'published'::public.post_status not null,
  moderation_note text,
  moderated_at timestamp with time zone,
  moderated_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  max_viewer_age smallint
);
alter table public.posts add constraint posts_pkey primary key (id);
alter table public.posts add constraint posts_author_id_fkey foreign key (author_id) references public.profiles(id) on delete cascade;
alter table public.posts add constraint posts_moderated_by_fkey foreign key (moderated_by) references public.profiles(id) on delete set null;
alter table public.posts add constraint posts_caption_length check (caption is null or char_length(caption) <= 2200);
alter table public.posts add constraint posts_max_viewer_age_bounds check (max_viewer_age is null or (max_viewer_age >= 18 and max_viewer_age <= 100));
alter table public.posts add constraint posts_media_count check (cardinality(media_urls) >= 1 and cardinality(media_urls) <= 5);
alter table public.posts add constraint posts_media_no_blank_urls check (array_position(media_urls, ''::text) is null and array_position(media_urls, null::text) is null);
create index posts_author_idx on public.posts using btree (author_id, created_at desc);
create index posts_max_viewer_age_idx on public.posts using btree (max_viewer_age);
comment on column public.posts.max_viewer_age is 'Maximum viewer age allowed to see this post. NULL = no ceiling.';

create table public.ratings (
  id uuid default gen_random_uuid() not null,
  post_id uuid not null,
  user_id uuid not null,
  score smallint not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null
);
alter table public.ratings add constraint ratings_pkey primary key (id);
alter table public.ratings add constraint ratings_one_per_user_per_post unique (post_id, user_id);
alter table public.ratings add constraint ratings_post_id_fkey foreign key (post_id) references public.posts(id) on delete cascade;
alter table public.ratings add constraint ratings_user_id_fkey foreign key (user_id) references public.profiles(id) on delete cascade;
alter table public.ratings add constraint ratings_score_range check (score >= 1 and score <= 5);
create index ratings_post_idx on public.ratings using btree (post_id);

create table public.comments (
  id uuid default gen_random_uuid() not null,
  post_id uuid not null,
  author_id uuid not null,
  body text not null,
  is_hidden boolean default false not null,
  moderation_note text,
  moderated_at timestamp with time zone,
  moderated_by uuid,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null
);
alter table public.comments add constraint comments_pkey primary key (id);
alter table public.comments add constraint comments_post_id_fkey foreign key (post_id) references public.posts(id) on delete cascade;
alter table public.comments add constraint comments_author_id_fkey foreign key (author_id) references public.profiles(id) on delete cascade;
alter table public.comments add constraint comments_moderated_by_fkey foreign key (moderated_by) references public.profiles(id) on delete set null;
alter table public.comments add constraint comments_body_length check (char_length(btrim(body)) >= 1 and char_length(btrim(body)) <= 1000);
create index comments_post_created_idx on public.comments using btree (post_id, created_at);

create table public.bookmarks (
  user_id uuid not null,
  post_id uuid not null,
  created_at timestamp with time zone default now() not null
);
alter table public.bookmarks add constraint bookmarks_pkey primary key (user_id, post_id);
alter table public.bookmarks add constraint bookmarks_post_id_fkey foreign key (post_id) references public.posts(id) on delete cascade;
alter table public.bookmarks add constraint bookmarks_user_id_fkey foreign key (user_id) references public.profiles(id) on delete cascade;

create table public.reports (
  id uuid default gen_random_uuid() not null,
  reporter_id uuid not null,
  post_id uuid,
  comment_id uuid,
  reason public.report_reason not null,
  details text,
  resolved_at timestamp with time zone,
  resolved_by uuid,
  resolution_note text,
  created_at timestamp with time zone default now() not null
);
alter table public.reports add constraint reports_pkey primary key (id);
alter table public.reports add constraint reports_reporter_id_fkey foreign key (reporter_id) references public.profiles(id) on delete cascade;
alter table public.reports add constraint reports_post_id_fkey foreign key (post_id) references public.posts(id) on delete cascade;
alter table public.reports add constraint reports_comment_id_fkey foreign key (comment_id) references public.comments(id) on delete cascade;
alter table public.reports add constraint reports_resolved_by_fkey foreign key (resolved_by) references public.profiles(id) on delete set null;
alter table public.reports add constraint reports_details_length check (details is null or char_length(details) <= 1000);
alter table public.reports add constraint reports_target_check check ((post_id is not null and comment_id is null) or (post_id is null and comment_id is not null));
create index reports_open_idx on public.reports using btree (resolved_at, created_at desc);

-- ---------------------------------------------------------------------------
-- Functions
-- ---------------------------------------------------------------------------

create or replace function public.is_adult(birth_date date)
returns boolean
language sql
stable
set search_path to 'public'
as $$
  select birth_date is not null and birth_date <= (current_date - interval '18 years')::date;
$$;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create or replace function public.enforce_profile_gate()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  if not public.is_adult(new.date_of_birth) then
    raise exception 'Dashing accounts require a verified age of 18 or older'
      using errcode = 'check_violation';
  end if;

  -- Clients cannot grant themselves moderator privileges. A database owner or
  -- service-role administrative process may assign the role outside client RLS.
  if tg_op = 'UPDATE' and new.is_moderator is distinct from old.is_moderator
     and current_user not in ('postgres', 'supabase_admin', 'service_role') then
    raise exception 'Moderator role may only be changed by an administrator'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;

create or replace function private.current_user_is_adult()
returns boolean
language sql
stable security definer
set search_path to 'pg_catalog', 'private'
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and public.is_adult(date_of_birth)
  );
$$;

create or replace function private.current_user_is_moderator()
returns boolean
language sql
stable security definer
set search_path to 'pg_catalog', 'private'
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and is_moderator
  );
$$;

create or replace function private.enforce_post_author_gate()
returns trigger
language plpgsql
security definer
set search_path to 'pg_catalog', 'private'
as $$
begin
  if not exists (
    select 1 from public.profiles
    where id = new.author_id and public.is_adult(date_of_birth)
  ) then
    raise exception 'Only profiles age 18 or older may create posts'
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

-- NOTE: references posts.viewer_min_age, which no longer exists. Every
-- rating/comment/bookmark insert fails. Fixed in the next migration.
create or replace function private.enforce_interaction_target()
returns trigger
language plpgsql
security definer
set search_path to 'pg_catalog', 'private'
as $$
declare
  required_age smallint;
  target_status public.post_status;
begin
  select viewer_min_age, status into required_age, target_status
  from public.posts where id = new.post_id;

  if not found or target_status <> 'published' then
    raise exception 'Interactions require a published post' using errcode = 'check_violation';
  end if;

  if not exists (
    select 1 from public.profiles
    where id = auth.uid()
      and public.is_adult(date_of_birth)
      and date_of_birth <= (current_date - make_interval(years => required_age))::date
  ) then
    raise exception 'You do not meet this post''s viewer-age requirement' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------------

create trigger profiles_enforce_age_gate before insert or update on public.profiles for each row execute function public.enforce_profile_gate();
create trigger profiles_set_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create trigger posts_enforce_author_gate before insert or update of author_id on public.posts for each row execute function private.enforce_post_author_gate();
create trigger posts_set_updated_at before update on public.posts for each row execute function public.set_updated_at();
create trigger ratings_enforce_target before insert or update of post_id on public.ratings for each row execute function private.enforce_interaction_target();
create trigger ratings_set_updated_at before update on public.ratings for each row execute function public.set_updated_at();
create trigger comments_enforce_target before insert or update of post_id on public.comments for each row execute function private.enforce_interaction_target();
create trigger comments_set_updated_at before update on public.comments for each row execute function public.set_updated_at();
create trigger bookmarks_enforce_target before insert or update of post_id on public.bookmarks for each row execute function private.enforce_interaction_target();

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------

alter table public.profiles enable row level security;
alter table public.posts enable row level security;
alter table public.ratings enable row level security;
alter table public.comments enable row level security;
alter table public.bookmarks enable row level security;
alter table public.reports enable row level security;

create policy "Users and moderators can view profiles" on public.profiles for select to authenticated
using (id = auth.uid() or private.current_user_is_moderator());
create policy "Users can create their own adult profile" on public.profiles for insert to authenticated
with check (id = auth.uid() and public.is_adult(date_of_birth) and not is_moderator and country is not null and city is not null);
create policy "Users can update their own profile" on public.profiles for update to authenticated
using (id = auth.uid())
with check (id = auth.uid() and public.is_adult(date_of_birth) and not is_moderator and country is not null and city is not null);

create policy "Authors and moderators can view posts" on public.posts for select to authenticated
using (
  author_id = auth.uid()
  or private.current_user_is_moderator()
  or (
    status = 'published'::public.post_status
    and private.current_user_is_adult()
    and (
      max_viewer_age is null
      or exists (
        select 1 from public.profiles viewer
        where viewer.id = auth.uid()
          and viewer.date_of_birth >= (current_date - make_interval(years => posts.max_viewer_age::integer))::date
      )
    )
  )
);
create policy "Adult users can create their own posts" on public.posts for insert to authenticated
with check (
  author_id = auth.uid()
  and private.current_user_is_adult()
  and (max_viewer_age is null or (max_viewer_age >= 18 and max_viewer_age <= 100))
  and cardinality(media_urls) >= 1 and cardinality(media_urls) <= 5
  and status = any (array['draft'::public.post_status, 'published'::public.post_status])
  and moderated_by is null and moderated_at is null and moderation_note is null
);
create policy "Authors can update their unmoderated posts" on public.posts for update to authenticated
using (author_id = auth.uid())
with check (
  author_id = auth.uid()
  and private.current_user_is_adult()
  and (max_viewer_age is null or (max_viewer_age >= 18 and max_viewer_age <= 100))
  and cardinality(media_urls) >= 1 and cardinality(media_urls) <= 5
  and status = any (array['draft'::public.post_status, 'published'::public.post_status])
  and moderated_by is null and moderated_at is null and moderation_note is null
);
create policy "Authors can delete their posts" on public.posts for delete to authenticated
using (author_id = auth.uid());
create policy "Moderators can manage posts" on public.posts for all to authenticated
using (private.current_user_is_moderator()) with check (private.current_user_is_moderator());

create policy "Eligible adult users can view ratings" on public.ratings for select to authenticated
using (exists (select 1 from public.posts where posts.id = ratings.post_id));
create policy "Users can create their own ratings" on public.ratings for insert to authenticated
with check (user_id = auth.uid() and private.current_user_is_adult());
create policy "Users can update their own ratings" on public.ratings for update to authenticated
using (user_id = auth.uid()) with check (user_id = auth.uid() and private.current_user_is_adult());
create policy "Users can delete their own ratings" on public.ratings for delete to authenticated
using (user_id = auth.uid());

create policy "Eligible adult users can view comments" on public.comments for select to authenticated
using ((not is_hidden and exists (select 1 from public.posts where posts.id = comments.post_id)) or author_id = auth.uid() or private.current_user_is_moderator());
create policy "Users can write their own comments" on public.comments for insert to authenticated
with check (author_id = auth.uid() and private.current_user_is_adult() and not is_hidden and moderated_by is null and moderated_at is null);
create policy "Authors can update their own comments" on public.comments for update to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid() and not is_hidden and moderated_by is null and moderated_at is null);
create policy "Authors can delete their own comments" on public.comments for delete to authenticated
using (author_id = auth.uid());
create policy "Moderators can manage comments" on public.comments for all to authenticated
using (private.current_user_is_moderator()) with check (private.current_user_is_moderator());

create policy "Users can manage only their own bookmarks" on public.bookmarks for all to authenticated
using (user_id = auth.uid()) with check (user_id = auth.uid() and private.current_user_is_adult());

create policy "Users can file their own reports" on public.reports for insert to authenticated
with check (reporter_id = auth.uid() and private.current_user_is_adult() and resolved_at is null and resolved_by is null);
create policy "Reporters and moderators can view reports" on public.reports for select to authenticated
using (reporter_id = auth.uid() or private.current_user_is_moderator());
create policy "Moderators can resolve reports" on public.reports for update to authenticated
using (private.current_user_is_moderator()) with check (private.current_user_is_moderator());

-- ---------------------------------------------------------------------------
-- Views
-- ---------------------------------------------------------------------------

create view public.profile_cards with (security_barrier = true, security_invoker = true) as
select id, username, display_name, avatar_url, bio, created_at
from public.profiles
where private.current_user_is_adult();

create materialized view public.post_leaderboard as
select
  p.id as post_id,
  p.author_id,
  p.max_viewer_age,
  p.created_at,
  count(r.*)::integer as rating_count,
  round(avg(r.score), 2) as average_rating,
  coalesce(sum(r.score), 0::bigint)::integer as rating_total
from public.posts p
join public.ratings r on r.post_id = p.id
where p.status = 'published'::public.post_status
group by p.id, p.author_id, p.max_viewer_age, p.created_at
having count(r.*) > 0;
create unique index post_leaderboard_post_id_idx on public.post_leaderboard using btree (post_id);
create index post_leaderboard_rating_idx on public.post_leaderboard using btree (average_rating desc, rating_count desc);

-- NOTE: calls public.current_user_is_moderator(), which no longer exists.
create or replace function public.refresh_post_leaderboard()
returns void
language plpgsql
security definer
set search_path to 'public'
as $$
begin
  if not public.current_user_is_moderator() then
    raise exception 'Only moderators may refresh the leaderboard' using errcode = 'insufficient_privilege';
  end if;
  refresh materialized view public.post_leaderboard;
end;
$$;

create or replace function public.get_post_leaderboard(result_limit integer default 50)
returns table(post_id uuid, author_id uuid, max_viewer_age smallint, created_at timestamp with time zone, rating_count integer, average_rating numeric, rating_total integer)
language sql
stable security definer
set search_path to 'pg_catalog', 'private'
as $$
  select l.post_id, l.author_id, l.max_viewer_age, l.created_at,
         l.rating_count, l.average_rating, l.rating_total
  from public.post_leaderboard l
  join public.profiles viewer on viewer.id = auth.uid()
  where public.is_adult(viewer.date_of_birth)
    and (
      l.max_viewer_age is null
      or viewer.date_of_birth >= (current_date - make_interval(years => l.max_viewer_age::integer))::date
    )
  order by l.average_rating desc, l.rating_count desc, l.created_at desc
  limit greatest(1, least(coalesce(result_limit, 50), 100));
$$;

-- ---------------------------------------------------------------------------
-- Privileges (as found live; tables keep Supabase's default grants)
-- ---------------------------------------------------------------------------

revoke all on public.profile_cards from public, anon;
grant select on public.profile_cards to authenticated;
revoke select on public.post_leaderboard from anon, authenticated;

revoke all on function private.current_user_is_adult() from public, anon, authenticated;
revoke all on function private.current_user_is_moderator() from public, anon;
grant execute on function private.current_user_is_moderator() to authenticated;
revoke all on function private.enforce_post_author_gate() from public, anon, authenticated;
revoke all on function private.enforce_interaction_target() from public, anon, authenticated;
grant execute on all functions in schema private to service_role;

revoke all on function public.refresh_post_leaderboard() from public, anon;
grant execute on function public.refresh_post_leaderboard() to authenticated;
revoke all on function public.get_post_leaderboard(integer) from public, anon;
grant execute on function public.get_post_leaderboard(integer) to authenticated;

-- ---------------------------------------------------------------------------
-- Storage: private post-media bucket
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('post-media', 'post-media', false, 8388608, array['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
on conflict (id) do nothing;

create policy "Authors upload to their own folder" on storage.objects for insert to authenticated
with check (bucket_id = 'post-media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Authors manage their own media" on storage.objects for update to authenticated
using (bucket_id = 'post-media' and (storage.foldername(name))[1] = auth.uid()::text)
with check (bucket_id = 'post-media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Authors delete their own media" on storage.objects for delete to authenticated
using (bucket_id = 'post-media' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Adults read media of visible posts" on storage.objects for select to authenticated
using (
  bucket_id = 'post-media'
  and exists (
    select 1
    from public.posts p
    join public.profiles viewer on viewer.id = auth.uid()
    where p.status = 'published'::public.post_status
      and p.media_urls @> array[objects.name]
      and public.is_adult(viewer.date_of_birth)
      and (
        p.max_viewer_age is null
        or viewer.date_of_birth >= (current_date - make_interval(years => p.max_viewer_age::integer))::date
      )
  )
);
